Test("Timer pause freezes remainder", () => { var c = new FakeClock(); var t = new FocusTimer(c); t.Start(); c.Advance(TimeSpan.FromMinutes(2)); t.Pause(); c.Advance(TimeSpan.FromHours(2)); Equal(TimeSpan.FromMinutes(23), t.Remaining); });
