Test("Store roundtrips preferences and workspace", () => { var root=TempFolder();try { var s=new LocalStore(root);s.Save("preferences.json",new Preferences{Theme="Light"});Equal("Light",s.Load("preferences.json",new Preferences()).Theme);s.Save("workspace.json",new WorkspaceData{Note="local"});Equal("local",s.Load("workspace.json",new WorkspaceData()).Note); } finally { if(Directory.Exists(root))Directory.Delete(root,true); } });
Test("Store recovers previous version from atomic backup", () => { var root=TempFolder();try{var s=new LocalStore(root);s.Save("workspace.json",new WorkspaceData{Note="first"});s.Save("workspace.json",new WorkspaceData{Note="second"});File.WriteAllText(Path.Combine(root,"workspace.json"),"{broken");Equal("first",s.Load("workspace.json",new WorkspaceData()).Note);}finally{if(Directory.Exists(root))Directory.Delete(root,true);} });
Test("Store rejects path traversal", () => { var s=new LocalStore(TempFolder());Throws<ArgumentException>(()=>s.Save("../outside.json",new{})); });
Test("Store refuses oversized persistence", () => { var root=TempFolder();try{var s=new LocalStore(root);Throws<InvalidDataException>(()=>s.Save("workspace.json",new string('x',2_000_001)));}finally{if(Directory.Exists(root))Directory.Delete(root,true);} });
Test("DeleteAll removes app data and suppresses resurrection", () => { var root=TempFolder();var s=new LocalStore(root);s.Save("workspace.json",new WorkspaceData{Note="delete"});s.DeleteAll();s.Save("workspace.json",new WorkspaceData());Assert(!Directory.Exists(root)); });
Test("DeleteAll never follows an unexpected nested directory", () => { var root=TempFolder();try{Directory.CreateDirectory(Path.Combine(root,"unexpected"));var s=new LocalStore(root);Throws<IOException>(s.DeleteAll);Assert(Directory.Exists(root));}finally{if(Directory.Exists(root))Directory.Delete(root,true);} });
Test("Diagnostics accept fixed codes only", () => { var root=TempFolder();try{var d=new Diagnostics(root);d.Record("secret personal path");Assert(!Directory.Exists(root));d.Record("TEST_EVENT");var text=File.ReadAllText(Path.Combine(root,"diagnostics.log"));Assert(text.Contains("TEST_EVENT")&&!text.Contains("secret"));}finally{if(Directory.Exists(root))Directory.Delete(root,true);} });
