AsyncTest("Weather sends only declared fields and parses response", async () => { using var p=new NetworkConsent();p.Grant();var a=new NetworkAudit(new FakeClock());var h=new FakeTransport();using var client=new WeatherClient(p,a,h);var w=await client.FetchAsync(12.345678,76.987654);Equal(23.5,w.TemperatureC);Equal(1,h.Calls);Assert(h.LastUri!.Query.Contains("latitude=12.3457"));Assert(!h.LastUri.Query.Contains("user")&&!h.LastUri.Query.Contains("track"));Equal("success",a.Entries[0].Outcome);Assert(!JsonSerializer.Serialize(a.Entries).Contains("12.3457")); });
AsyncTest("Weather does not silently accept redirects", async () => { using var p=new NetworkConsent();p.Grant();var h=new FakeTransport{Status=HttpStatusCode.Redirect};using var client=new WeatherClient(p,new(new FakeClock()),h);await ThrowsAsync<HttpRequestException>(()=>client.FetchAsync(0,0));Equal(1,h.Calls); });
AsyncTest("Weather malformed responses fail with audit", async () => { using var p=new NetworkConsent();p.Grant();var a=new NetworkAudit(new FakeClock());using var client=new WeatherClient(p,a,new FakeTransport{Body="{}"});await ThrowsAsync<KeyNotFoundException>(()=>client.FetchAsync(0,0));Equal("failed",a.Entries[0].Outcome); });
AsyncTest("Weather revocation cancels transport", async () => { using var p=new NetworkConsent();p.Grant();var h=new FakeTransport{WaitForCancellation=true};var a=new NetworkAudit(new FakeClock());using var client=new WeatherClient(p,a,h);var task=client.FetchAsync(0,0);await h.Started.Task.WaitAsync(TimeSpan.FromSeconds(2));p.Revoke();await ThrowsAsync<OperationCanceledException>(()=>task);Equal("cancelled-or-timeout",a.Entries[0].Outcome); });

