Test("Atmosphere is opaque, darkened and deterministic",()=>{var source=Enumerable.Repeat(new byte[]{200,120,60,255},16*16).SelectMany(x=>x).ToArray();var a=AtmosphereRenderer.Render(source,16,16,128,80);var b=AtmosphereRenderer.Render(source,16,16,128,80);Assert(a.SequenceEqual(b));for(var i=0;i<a.Length;i+=4){Equal((byte)255,a[i+3]);Assert(a[i]<100&&a[i+1]<65&&a[i+2]<35);}});
Test("Atmosphere smooths cover edges and changes with art",()=>{var source=new byte[16*16*4];for(int i=0;i<16*16;i++){source[i*4]=(byte)(i%16<8?240:0);source[i*4+2]=(byte)(i%16<8?0:240);source[i*4+3]=255;}var a=AtmosphereRenderer.Render(source,16,16,128,80);for(int x=1;x<128;x++)Assert(Math.Abs(a[(40*128+x)*4]-a[(40*128+x-1)*4])<8);var b=AtmosphereRenderer.Render(new byte[source.Length],16,16,128,80);Assert(!a.SequenceEqual(b));});
Test("Atmosphere rejects invalid buffers and honors cancellation",()=>{Throws<ArgumentOutOfRangeException>(()=>AtmosphereRenderer.Render(new byte[4],256,256,128,80));using var c=new CancellationTokenSource();c.Cancel();Throws<OperationCanceledException>(()=>AtmosphereRenderer.Render(new byte[16*16*4],16,16,128,80,c.Token));});
Test("Spring converges without excessive bounce",()=>{var s=new SpringValue(248){Target=560};double max=0;for(int i=0;i<240;i++){s.Step(1d/120,new());max=Math.Max(max,s.Position);}Assert(s.Settled);Assert(max<565);Equal(560d,s.Position);});
Test("Spring preserves velocity on interrupted expansion",()=>{var s=new SpringValue(248){Target=560};s.Step(.08,new());var velocity=s.Velocity;var position=s.Position;s.Target=248;Equal(velocity,s.Velocity);Equal(position,s.Position);for(int i=0;i<240;i++)s.Step(1d/120,new());Equal(248d,s.Position);});
Test("Spring is stable across 60 and 120 Hz",()=>{var a=new SpringValue(0){Target=1};var b=new SpringValue(0){Target=1};for(int i=0;i<18;i++)a.Step(1d/60,new());for(int i=0;i<36;i++)b.Step(1d/120,new());Assert(Math.Abs(a.Position-b.Position)<1e-10);});
Test("Spring analytic solution handles critical damping",()=>{var s=new SpringValue(0){Target=100};var c=new SpringConfiguration(400,40,1);s.Step(2,c);Assert(s.Settled);Equal(100d,s.Position);});
Test("Spring analytic solution handles overdamping",()=>{var s=new SpringValue(0){Target=100};for(int i=0;i<600;i++)s.Step(1d/120,new(400,80,1));Assert(s.Settled);Equal(100d,s.Position);});
Test("Spring rejects invalid elapsed time",()=>{var s=new SpringValue(0);Throws<ArgumentOutOfRangeException>(()=>s.Step(double.NaN,new()));Throws<ArgumentOutOfRangeException>(()=>s.Step(-1,new()));});
Test("Spring parameters clamp to safe finite bounds",()=>{var c=new SpringConfiguration(double.NaN,-100,0).Validated();Equal(420d,c.Stiffness);Equal(10d,c.Damping);Equal(.5,c.Mass);});
Test("Opening motion reaches useful size quickly with controlled overshoot",()=>{var c=IslandMotionProfile.Create(new(),true);var w=new SpringValue(224){Target=560};var h=new SpringValue(40){Target=334};double peak=0;for(int i=0;i<120;i++){w.Step(1d/120,c.Width);h.Step(1d/120,c.Height);peak=Math.Max(peak,w.Position);if(i==29){Assert(w.Position>224+.9*(560-224));Assert(h.Position>40+.85*(334-40));}}Assert(peak<560+(560-224)*.035);Assert(w.Settled&&h.Settled);});
Test("Closing motion settles without an elastic undershoot",()=>{var c=IslandMotionProfile.Create(new(),false);var s=new SpringValue(334){Target=40};for(int i=0;i<120;i++){s.Step(1d/120,c.Height);Assert(s.Position>=39.98);}Assert(s.Settled);});
Test("Motion profile changes preserve interruption momentum",()=>{var s=new SpringValue(40){Target=334};s.Step(.09,IslandMotionProfile.Create(new(),true).Height);var v=s.Velocity;var p=s.Position;s.Target=40;var closing=IslandMotionProfile.Create(new(),false);Equal(v,s.Velocity);Equal(p,s.Position);s.Step(1d/120,closing.Height);Assert(double.IsFinite(s.Position));for(int i=0;i<120;i++)s.Step(1d/120,closing.Height);Assert(s.Settled);});
Test("Tuned motion is frame-rate independent",()=>{var c=IslandMotionProfile.Create(new(),true);var a=new SpringValue(40){Target=334};var b=new SpringValue(40){Target=334};for(int i=0;i<18;i++)a.Step(1d/60,c.Height);for(int i=0;i<36;i++)b.Step(1d/120,c.Height);Assert(Math.Abs(a.Position-b.Position)<1e-9);});
