Test("Changing retained activity page marks transition",()=>{var s=new IslandStateMachine(new FakeClock());s.Expand();s.MarkSettled();s.Select(IslandPage.Shelf);Equal(IslandState.Transition,s.Current);Equal(IslandPage.Shelf,s.Page);});

Test("Auto-stow includes maximized and fullscreen apps",()=>{Assert(ForegroundPolicy.ShouldStow(true,false,false,true,false));Assert(ForegroundPolicy.ShouldStow(true,false,false,false,true));});
Test("Minimizing the last app restores a resting desktop pill",()=>{var m=new IslandStateMachine(new FakeClock());m.SetStowed(true);m.SetStowed(ForegroundPolicy.ShouldStow(true,true,false,true,true,false));Assert(m.Target==IslandState.Idle);m.SetActivity(new(ActivityKind.Focus,20,"Focus"),ActivityKind.Focus);m.SetStowed(true);m.SetStowed(false);Assert(m.Target==IslandState.PersistentActivity);});
Test("All minimized clears stow even with stale maximized foreground",()=>{Assert(!ForegroundPolicy.ShouldStow(true,false,false,true,true,false));Assert(!ForegroundPolicy.ShouldStow(true,true,false,true,true,false));});
Test("Auto-stow excludes own UI, shell and normal windows",()=>{Assert(!ForegroundPolicy.ShouldStow(true,true,false,true,false));Assert(!ForegroundPolicy.ShouldStow(true,false,true,true,false));Assert(!ForegroundPolicy.ShouldStow(true,false,false,false,false));Assert(!ForegroundPolicy.ShouldStow(false,false,false,true,true));});
Test("Stowed island peeks on hover and returns to upper bar",()=>{var s=new IslandStateMachine(new FakeClock());s.SetStowed(true);Equal(IslandState.Stowed,s.Target);s.Hover(true);Equal(IslandState.Hover,s.Target);s.Hover(false);Equal(IslandState.Stowed,s.Target);});
Test("Stow policy preserves explicit expansion",()=>{var s=new IslandStateMachine(new FakeClock());s.Expand();s.SetStowed(true);Equal(IslandState.Expanded,s.Target);s.Collapse();Equal(IslandState.Stowed,s.Target);});
Test("Activity updates do not un-stow the island",()=>{var s=new IslandStateMachine(new FakeClock());s.SetStowed(true);s.SetActivity(new(ActivityKind.Focus,20,"Focus"),ActivityKind.Focus);Equal(IslandState.Stowed,s.Target);});
Test("System HUD clamps levels without changing foreground policy",()=>{var s=new IslandStateMachine(new FakeClock());s.ShowSystemHud(SystemHudKind.Volume,120);Equal(100d,s.HudValue);Equal(IslandState.SystemHud,s.Target);s.ShowSystemHud(SystemHudKind.Brightness,double.NaN);Equal(0d,s.HudValue);});
Test("System HUD returns to the stowed strip",()=>{var c=new FakeClock();var s=new IslandStateMachine(c);s.SetStowed(true);s.ShowSystemHud(SystemHudKind.Volume,50);c.Advance(TimeSpan.FromSeconds(2));s.Tick();Equal(IslandState.Stowed,s.Target);});
Test("System HUD restores an expanded activity",()=>{var c=new FakeClock();var s=new IslandStateMachine(c);s.Expand(IslandPage.Controls);s.ShowSystemHud(SystemHudKind.Brightness,40);c.Advance(TimeSpan.FromSeconds(2));s.Tick();Equal(IslandState.Expanded,s.Target);Equal(IslandPage.Controls,s.Page);});
Test("Repeated volume events extend HUD lifetime",()=>{var c=new FakeClock();var s=new IslandStateMachine(c);s.ShowSystemHud(SystemHudKind.Volume,20);c.Advance(TimeSpan.FromSeconds(1));s.ShowSystemHud(SystemHudKind.Volume,22);c.Advance(TimeSpan.FromSeconds(1));s.Tick();Equal(IslandState.SystemHud,s.Target);c.Advance(TimeSpan.FromSeconds(1));s.Tick();Equal(IslandState.Idle,s.Target);});
Test("Explicit hidden preference suppresses system HUD",()=>{var s=new IslandStateMachine(new FakeClock());s.SetHidden(true);s.ShowSystemHud(SystemHudKind.Volume,20);Equal(IslandState.Hidden,s.Target);});
Test("Standard volume keys map only while enabled",()=>{Equal<HardwareAction?>(HardwareAction.VolumeUp,HardwareKeyPolicy.Resolve(0xAF,true,false,0,0,false));Equal<HardwareAction?>(HardwareAction.VolumeDown,HardwareKeyPolicy.Resolve(0xAE,true,false,0,0,false));Equal<HardwareAction?>(null,HardwareKeyPolicy.Resolve(0xAF,false,false,0,0,false));});
Test("Ordinary text keys are never media controls",()=>{for(var k=0x30;k<=0x5A;k++)Equal<HardwareAction?>(null,HardwareKeyPolicy.Resolve(k,true,true,0,0,false));});
Test("Brightness learning rejects text keys",()=>{Assert(!HardwareKeyPolicy.IsAssignableBrightnessKey(0x41));Assert(!HardwareKeyPolicy.IsAssignableBrightnessKey(0x31));Assert(HardwareKeyPolicy.IsAssignableBrightnessKey(0x75));});
Test("Only configured brightness keys are consumed",()=>{Equal<HardwareAction?>(HardwareAction.BrightnessDown,HardwareKeyPolicy.Resolve(0x75,true,true,0x75,0x76,false));Equal<HardwareAction?>(null,HardwareKeyPolicy.Resolve(0x74,true,true,0x75,0x76,false));});
Test("Brightness shortcuts require Control and Alt",()=>{Equal<HardwareAction?>(HardwareAction.BrightnessUp,HardwareKeyPolicy.Resolve(0x26,false,false,0,0,true));Equal<HardwareAction?>(null,HardwareKeyPolicy.Resolve(0x26,true,true,0,0,false));});
Test("Integration preferences validate material and learned keys",()=>{var p=new Preferences{BrightnessDownKey=0x41,TaskbarTintOpacity=500,GlassShine=double.NaN}.Validated();Equal(0,p.BrightnessDownKey);Equal(220,p.TaskbarTintOpacity);Equal(1.4,p.GlassShine);});

var failures=0; var results=new List<object>();
foreach(var test in tests)
{
 try { await test.Run(); Console.WriteLine("PASS " + test.Name);results.Add(new{name=test.Name,passed=true}); }
 catch(Exception error) { failures++;Console.WriteLine("FAIL " + test.Name + ": " + error.Message);results.Add(new{name=test.Name,passed=false,error=error.GetType().Name}); }
}
Console.WriteLine($"{tests.Count-failures}/{tests.Count} tests passed. No live external network requests were made.");
if(args.Length==2 && args[0]=="--report")File.WriteAllText(args[1],JsonSerializer.Serialize(new{total=tests.Count,passed=tests.Count-failures,failed=failures,results},new JsonSerializerOptions{WriteIndented=true}));
return failures==0?0:1;

sealed class FakeClock : IClock
{
 public DateTimeOffset UtcNow {get;private set;}=new(2026,1,1,0,0,0,TimeSpan.Zero);
 public void Advance(TimeSpan by)=>UtcNow+=by;
}
sealed class FakeTransport : HttpMessageHandler
{
 public int Calls {get;private set;}
 public Uri? LastUri {get;private set;}
 public HttpStatusCode Status {get;init;}=HttpStatusCode.OK;
 public string Body {get;init;}="{\"current\":{\"temperature_2m\":23.5,\"wind_speed_10m\":9.2,\"weather_code\":1}}";
 public bool WaitForCancellation {get;init;}
 public TaskCompletionSource Started {get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);
 protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token)
 {Calls++;LastUri=request.RequestUri;Started.TrySetResult();if(WaitForCancellation)await Task.Delay(Timeout.Infinite,token);return new(Status){Content=new StringContent(Body,Encoding.UTF8,"application/json")};}
}
